def solve_sb26():
    import numpy as np
    g = grid()

    # Piece sources are the colored blocks in the bottom tray.
    sources = []
    for y in range(54, 64):
        for x in range(1, 63):
            c = int(g[y, x])
            if c not in (0, 4, 5, 14, 15):
                same = np.argwhere(g[54:64] == c)
                if len(same) >= 12:
                    sources.append((c, x, y))
    by_color = {}
    for c, x, y in sources:
        by_color.setdefault(c, []).append((x, y))
    sources = [(c, int(round(sum(x for x, y in pts)/len(pts))),
                   int(round(sum(y for x, y in pts)/len(pts))))
               for c, pts in by_color.items()]

    # Target colors are the framed blocks across the top.
    targets = []
    seen = set()
    for x in range(1, 63):
        vals = [int(g[y, x]) for y in range(2, 10)]
        useful = [c for c in vals if c not in (0, 4, 5, 14, 15)]
        if useful:
            c = max(set(useful), key=useful.count)
            if c not in seen:
                targets.append(c)
                seen.add(c)

    # Central red pads, ordered left to right.
    red = np.argwhere(g == 2)
    pads = []
    for y, x in red:
        if 20 < y < 40:
            if not pads or x - pads[-1][0] > 3:
                pads.append((int(x), int(y)))
    # Collapse each pad to its component center.
    comps = []
    todo = {(int(y), int(x)) for y, x in red if 20 < y < 40}
    while todo:
        seed = todo.pop()
        stack = [seed]
        comp = [seed]
        while stack:
            yy, xx = stack.pop()
            for nb in ((yy-1,xx),(yy+1,xx),(yy,xx-1),(yy,xx+1)):
                if nb in todo:
                    todo.remove(nb); stack.append(nb); comp.append(nb)
        comps.append((sum(x for y,x in comp)//len(comp),
                      sum(y for y,x in comp)//len(comp)))
    comps.sort()

    smap = {c:(x,y) for c,x,y in sources}
    for c, dest in zip(targets, comps):
        if c in smap:
            click(*smap[c])
            click(*dest)
    press(5)

import numpy as np
def _vc33_comps(col):
    a=grid(); m=(a==col); seen=np.zeros_like(m,bool); out=[]
    for y,x in zip(*np.where(m)):
        if seen[y,x]: continue
        st=[(y,x)]; seen[y,x]=1; pts=[]
        while st:
            yy,xx=st.pop(); pts.append((yy,xx))
            for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                ny,nx=yy+dy,xx+dx
                if 0<=ny<64 and 0<=nx<64 and m[ny,nx] and not seen[ny,nx]:
                    seen[ny,nx]=1; st.append((ny,nx))
        ys=[p[0] for p in pts]; xs=[p[1] for p in pts]
        out.append({"cx":sum(xs)/len(xs),"cy":sum(ys)/len(ys)})
    return out
def solve_vc33_level():
    start=levels()
    for _ in range(40):
        if not alive() or levels()>start: return levels()>start
        p=_vc33_comps(11); b=_vc33_comps(9)
        if len(p)<2 or len(b)<2: return False
        target=min(p,key=lambda z:z["cy"]); mover=max(p,key=lambda z:z["cy"])
        if abs(mover["cx"]-target["cx"])<1:
            press(6)
        else:
            upper=min(b,key=lambda z:z["cy"]); lower=max(b,key=lambda z:z["cy"])
            q=upper if mover["cx"]<target["cx"] else lower
            click(round(q["cx"]),round(q["cy"]))
    return levels()>start

def sp80_generic(limit=5000):
    import random
    old = levels()
    for i in range(limit):
        if not alive():
            reset()
        press(random.choice([1,2,2,3,4,6]))
        if levels() > old:
            reprobe()
            return True
    return False
